CREATE EXTENSION IF NOT EXISTS pgcrypto;
-- Adapter column names follow https://authjs.dev/getting-started/adapters/pg.
-- UUID identifiers replace SERIAL consistently across auth and business tables.
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, email text UNIQUE, "emailVerified" timestamptz, image text);
CREATE TABLE accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type varchar(255) NOT NULL, provider varchar(255) NOT NULL, "providerAccountId" varchar(255) NOT NULL, refresh_token text, access_token text, expires_at bigint, id_token text, scope text, session_state text, token_type text, UNIQUE(provider, "providerAccountId"));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires timestamptz NOT NULL, "sessionToken" varchar(255) NOT NULL UNIQUE);
CREATE TABLE verification_token (identifier text NOT NULL, expires timestamptz NOT NULL, token text NOT NULL, PRIMARY KEY(identifier, token));
CREATE TYPE work_order_status AS ENUM ('open','scheduled','in_progress','waiting_on_parts','done','cancelled');
CREATE TYPE work_order_priority AS ENUM ('low','normal','high','urgent');
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Dubai', is_demo boolean NOT NULL DEFAULT false, demo_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('admin','staff','client')), client_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,user_id), CHECK((role='client') = (client_id IS NOT NULL)), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id));
CREATE TABLE sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, name text NOT NULL, address text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id), UNIQUE(workspace_id,client_id,id));
CREATE TABLE work_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, site_id uuid NOT NULL, title text NOT NULL CHECK(length(trim(title))>0), description text NOT NULL DEFAULT '', external_ref text, source text NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','import','client')), status work_order_status NOT NULL DEFAULT 'open', priority work_order_priority NOT NULL DEFAULT 'normal', assignee_id uuid, scheduled_for timestamptz, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,client_id,site_id) REFERENCES sites(workspace_id,client_id,id), FOREIGN KEY(workspace_id,assignee_id) REFERENCES members(workspace_id,user_id), UNIQUE(workspace_id,client_id,id), UNIQUE(workspace_id,id));
CREATE TABLE comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_order_id uuid NOT NULL, workspace_id uuid NOT NULL, client_id uuid NOT NULL, body text NOT NULL CHECK(length(trim(body))>0), visibility text NOT NULL CHECK(visibility IN ('client','internal')), author_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,client_id,work_order_id) REFERENCES work_orders(workspace_id,client_id,id));
CREATE TABLE invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), client_id uuid, email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','staff','client')), token_hash text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','expired','revoked')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK((role='client')=(client_id IS NOT NULL)), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id));
CREATE TABLE imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), filename text NOT NULL, row_count integer NOT NULL CHECK(row_count BETWEEN 0 AND 500), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','queued','completed')), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE import_rows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, import_id uuid NOT NULL, row_number integer NOT NULL CHECK(row_number>0), data jsonb NOT NULL, errors jsonb NOT NULL DEFAULT '[]', ai_summary text, ai_priority work_order_priority, decision text NOT NULL DEFAULT 'pending' CHECK(decision IN ('pending','approved','rejected')), reason text, work_order_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(import_id,row_number), UNIQUE(work_order_id), FOREIGN KEY(workspace_id,import_id) REFERENCES imports(workspace_id,id), FOREIGN KEY(workspace_id,work_order_id) REFERENCES work_orders(workspace_id,id));
CREATE TABLE supplier_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, work_order_id uuid NOT NULL, cobalt_ref text NOT NULL UNIQUE, local_status text NOT NULL DEFAULT 'ordered' CHECK(local_status IN ('ordered','shipped','delivered','cancelled')), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,work_order_id) REFERENCES work_orders(workspace_id,id), UNIQUE(workspace_id,cobalt_ref));
CREATE TABLE supplier_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, cobalt_ref text NOT NULL, event_id text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('ordered','shipped','delivered','cancelled')), received_via text NOT NULL CHECK(received_via IN ('webhook','reconcile')), occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,cobalt_ref) REFERENCES supplier_orders(workspace_id,cobalt_ref));
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, actor_id uuid REFERENCES users(id), action text NOT NULL, entity text NOT NULL, entity_id uuid NOT NULL, "before" jsonb, "after" jsonb, at timestamptz NOT NULL DEFAULT now());
-- No workspace FK here: workspace deletion must preserve its audit history.
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, workspace_id uuid NOT NULL, kind text NOT NULL, entity_id uuid, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,user_id) REFERENCES members(workspace_id,user_id));
CREATE TABLE work_order_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, work_order_id uuid NOT NULL, actor_id uuid REFERENCES users(id), kind text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,client_id,work_order_id) REFERENCES work_orders(workspace_id,client_id,id));
CREATE INDEX work_orders_workspace_status ON work_orders(workspace_id,status,created_at);
CREATE INDEX work_orders_client ON work_orders(workspace_id,client_id);
CREATE INDEX comments_order ON comments(workspace_id,work_order_id);
CREATE INDEX audit_log_workspace_at ON audit_log(workspace_id,at);
CREATE INDEX notifications_user ON notifications(user_id,workspace_id);
